{"_displayName":"Configure Craft Workflow","_intent":"Create the DEX source, Craft skills, automation, labels, project guidance, and package scripts to integrate DEX with Craft Agents.","command":"python3 - <<'PY'
import json, time
from pathlib import Path
root = Path('/Users/mattias/Documents/GitHub/Systembolaget-plus')
now = int(time.time() * 1000)

# Update workspace config defaults
config_path = root / 'config.json'
config = json.loads(config_path.read_text())
config.setdefault('defaults', {})['enabledSourceSlugs'] = ['dex']
config['updatedAt'] = now
config_path.write_text(json.dumps(config, indent=2) + '\n')

# Update package.json scripts and devDependency (already installed)
pkg_path = root / 'package.json'
pkg = json.loads(pkg_path.read_text())
scripts = pkg.setdefault('scripts', {})
scripts['dex'] = 'dex --storage-path ./.dex'
scripts['dex:list'] = 'dex --storage-path ./.dex list'
scripts['dex:plan'] = 'dex --storage-path ./.dex plan'
scripts['dex:mcp'] = 'dex mcp --storage-path ./.dex'
pkg_path.write_text(json.dumps(pkg, indent=2) + '\n')

# Update labels
labels_path = root / 'labels' / 'config.json'
labels = json.loads(labels_path.read_text())
existing_ids = {label['id'] for label in labels['labels']}
if 'dex' not in existing_ids:
    labels['labels'].append({
        'id': 'dex',
        'name': 'DEX',
        'color': { 'light': '#14B8A6', 'dark': '#2DD4BF' }
    })
if 'review' not in existing_ids:
    labels['labels'].append({
        'id': 'review',
        'name': 'Review',
        'color': { 'light': '#F59E0B', 'dark': '#FBBF24' },
        'children': [
            {
                'id': 'approved',
                'name': 'Approved',
                'color': { 'light': '#22C55E', 'dark': '#4ADE80' }
            },
            {
                'id': 'changes-requested',
                'name': 'Changes Requested',
                'color': { 'light': '#EF4444', 'dark': '#F87171' }
            }
        ]
    })
if 'task-type' not in existing_ids:
    labels['labels'].append({
        'id': 'task-type',
        'name': 'Task Type',
        'color': 'accent',
        'children': [
            {
                'id': 'feature',
                'name': 'Feature',
                'color': { 'light': '#6366F1', 'dark': '#818CF8' }
            },
            {
                'id': 'refactor',
                'name': 'Refactor',
                'color': { 'light': '#8B5CF6', 'dark': '#A78BFA' }
            },
            {
                'id': 'research-task',
                'name': 'Research',
                'color': { 'light': '#EC4899', 'dark': '#F472B6' }
            }
        ]
    })
if 'dex-task' not in existing_ids:
    labels['labels'].append({
        'id': 'dex-task',
        'name': 'DEX Task',
        'color': 'foreground/60',
        'valueType': 'string'
    })
labels_path.write_text(json.dumps(labels, indent=2) + '\n')

# AGENTS.md
agents_md = root / 'AGENTS.md'
agents_md.write_text('''# Project Workflow\n\n## Task management\n\nUse **DEX + Craft Agents together** for any work that spans multiple steps, multiple files, or multiple sessions.\n\n### Default flow\n\n1. **Validate the plan first** with `@plan-validate`\n2. **Convert the validated plan into DEX tasks** with `@dex-backlog`\n3. **Start the next actionable task** with `@dex-next-task`\n4. Implement and verify the change\n5. Record the result in DEX, then set the Craft session status to **Needs Review**\n6. Let the review automation trigger `@dex-review`\n\n### Rules\n\n- Prefer the simplest solution that matches the request\n- Reuse existing patterns before introducing new abstractions\n- No scope creep during plan validation or review\n- Every DEX task should include:\n  - **What** will change\n  - **Why** it is needed\n  - **How** it should be approached\n  - **Done when** / verification criteria\n- Link implementation sessions to DEX using labels:\n  - `dex`\n  - `dex-task::<task-id>`\n\n### DEX storage\n\nThis repository uses repo-local DEX storage in [`.dex/`](./.dex/).\nUse the local CLI helpers:\n\n- `npm run dex:list`\n- `npm run dex -- create \"Task name\" --description \"...\"`\n- `npm run dex:plan -- <path-to-plan.md>`\n\n## Plan validation checklist\n\nWhen using `@plan-validate`, keep the validated plan intact and append a **Plan validation (review)** section with:\n\n- existing codebase patterns\n- framework/library best-practice findings\n- simplicity checks\n- dependency order validation\n- verification method validation\n- any scope reductions or clarifications\n''')

# Source files
source_dir = root / 'sources' / 'dex'
source_dir.mkdir(parents=True, exist_ok=True)
source_config = {
    'id': 'dex_7f12c9a4',
    'name': 'DEX',
    'slug': 'dex',
    'enabled': True,
    'provider': 'dex',
    'type': 'mcp',
    'icon': '🧩',
    'tagline': 'Persistent task tracking for multi-session work and automated review flows',
    'mcp': {
        'transport': 'stdio',
        'command': str(root / 'node_modules' / '.bin' / 'dex'),
        'args': ['mcp', '--storage-path', str(root / '.dex')],
        'authType': 'none'
    },
    'connectionStatus': 'untested',
    'createdAt': now,
    'updatedAt': now
}
(source_dir / 'config.json').write_text(json.dumps(source_config, indent=2) + '\n')
(source_dir / 'guide.md').write_text('''# DEX\n\nDEX is the persistent task backbone for this workspace. Use it for planning, task breakdown, multi-session continuity, and review-ready task results.\n\n## Scope\n\nThis source manages the repo-local task backlog stored in [`.dex/tasks.jsonl`](../../.dex/tasks.jsonl).\nUse it for:\n\n- validated implementation plans\n- parent tasks and subtasks\n- task start/completion tracking\n- implementation results and verification notes\n- handing work across sessions\n\n## Guidelines\n\n- Prefer DEX for work that spans more than one implementation step\n- Before creating tasks, validate the plan with `@plan-validate`\n- Create rich task context, not one-line todos\n- Results should include what changed, key decisions, and verification evidence\n- Link Craft sessions to DEX with labels `dex` and `dex-task::<task-id>`\n- When implementation is ready for review, move the Craft session to **Needs Review** so the review automation can inspect the task\n\n## Suggested workflow\n\n1. Validate the plan\n2. Convert the validated plan into DEX tasks or subtasks\n3. Start the next actionable task\n4. Implement and verify\n5. Record the result in DEX\n6. Set session status to `needs-review`\n7. Let the Craft automation run the review flow\n\n## Examples\n\n- Create a task from a validated plan file\n- List pending tasks and select the next unblocked task\n- Show a task's context and confirm the acceptance criteria before coding\n- Review a completed task's result before approving the implementation session\n''')
(source_dir / 'permissions.json').write_text(json.dumps({
    'allowedMcpPatterns': [
        { 'pattern': 'status', 'comment': 'Allow read-only status and dashboard operations' },
        { 'pattern': 'list', 'comment': 'Allow listing pending or completed tasks' },
        { 'pattern': 'show', 'comment': 'Allow viewing task details and recorded results' },
        { 'pattern': 'search', 'comment': 'Allow read-only task lookup operations if exposed' }
    ]
}, indent=2) + '\n')

# Skills
skills = {
    'plan-validate': {
        'name': 'Plan Validate',
        'description': 'Review an implementation plan for simplicity, existing patterns, and verification quality before execution.',
        'body': '''# Plan Validate\n\nUse this skill to review and validate an implementation plan **before execution**.\n\n## Goal\n\nReview the plan for simplicity, best practices, reuse of existing patterns, and testability.\n**Do not implement code changes while running this skill.**\n\n## Required outcome\n\nPreserve the full implementation plan and append a **Plan validation (review)** section to the same plan document.\n\n## Process\n\n### Step 1: Find existing patterns\n- Search the codebase for similar functionality\n- Prefer reuse over invention\n- Note any existing utilities, abstractions, or conventions the plan should follow\n\n### Step 2: Research framework best practices\n- If a Context7 source is available, use it for framework/library guidance\n- Otherwise use official docs and web research\n- Verify syntax, built-in capabilities, and whether the plan is re-implementing something already available\n\n### Step 3: Verify simplicity\nFor each plan item, ask:\n- Is this the simplest solution?\n- Does it only solve the requested problem?\n- Is it straightforward and easy to understand?\n\n**Red flags:** scope creep, extra features, unnecessary abstraction, over-engineering\n\n**Green flags:** reuses existing patterns, fixes a real problem directly, keeps verification simple\n\n### Step 4: Review against the codebase\nFor each plan item:\n- locate the relevant code\n- verify the problem exists\n- verify the proposed solution would actually fix it\n- challenge any unsupported assumptions\n\n### Step 5: Validate dependencies\n- Check that the order of work is sensible\n- Put foundations before higher-level logic\n- Ensure dependencies and blockers are explicit\n\n### Step 6: Validate verification methods\nFor each plan item:\n- confirm the verification method is available\n- confirm it can actually prove the fix worked\n- tighten vague acceptance criteria\n\n### Step 7: Update the plan\n- Remove complexity, duplication, and scope creep\n- Update the plan using findings from codebase research and docs\n- Keep each chunk testable with explicit **why / what / how / verification**\n\n## Output\n\nUpdate the same plan file with an additive **Plan validation (review)** section. Do not replace or shrink the implementation plan; refine it.\n'''
    },
    'dex-backlog': {
        'name': 'DEX Backlog',
        'description': 'Convert a validated plan into a DEX parent task and clean, testable subtasks with rich context.',
        'requiredSources': ['dex'],
        'body': '''# DEX Backlog\n\nUse this skill after a plan has been validated.\n\n## Goal\n\nTurn a validated plan into a DEX task hierarchy that is easy to execute across sessions.\n\n## Rules\n\n- Prefer one parent task plus clear subtasks\n- Break down by **testable chunks**, not by arbitrary file count\n- Keep subtasks atomic enough to verify independently\n- Every task should include:\n  - **What** changes\n  - **Why** it matters\n  - **How** to approach it\n  - **Done when** / verification\n\n## Process\n\n1. Read the validated plan file\n2. Identify the parent deliverable\n3. Identify 3-7 meaningful subtasks when appropriate\n4. Use DEX `plan` when the markdown structure is already clean\n5. If the automatic breakdown is weak, create or refine tasks manually\n6. Avoid creating subtasks that depend on hidden assumptions\n7. Preserve the dependency order from the validated plan\n\n## Craft session linkage\n\nIf this work is being tracked in a Craft session:\n- add the `dex` label\n- add `dex-task::<parent-or-active-task-id>`\n- keep the session in `backlog` until implementation starts\n\n## Output\n\nShow the created DEX parent task and subtasks, plus the recommended execution order.\n'''
    },
    'dex-next-task': {
        'name': 'DEX Next Task',
        'description': 'Select the next actionable DEX task, start it, and prepare a Craft session for implementation.',
        'requiredSources': ['dex'],
        'body': '''# DEX Next Task\n\nUse this skill to pick and start the next actionable DEX task.\n\n## Process\n\n1. List pending DEX tasks\n2. Ignore blocked or already-completed items\n3. Pick the highest-priority, most logical next task\n4. Read the task details before doing any implementation\n5. Start the chosen task in DEX\n6. Restate:\n   - scope\n   - assumptions\n   - files likely involved\n   - verification steps\n\n## Craft session linkage\n\nWhen operating inside Craft:\n- ensure the session has label `dex`\n- add `dex-task::<active-task-id>`\n- move the session into active work (`todo` or equivalent current execution state)\n\n## Guardrails\n\n- Do not start two overlapping tasks unless the user explicitly asks\n- If the next task is too large, stop and break it down further\n- If requirements are unclear, update the DEX task before coding\n\n## Output\n\nReturn the chosen task ID, why it was selected, and the verification checklist for implementation.\n'''
    },
    'dex-review': {
        'name': 'DEX Review',
        'description': 'Review a completed DEX-backed implementation session, verify the result, and approve or request changes.',
        'requiredSources': ['dex'],
        'body': '''# DEX Review\n\nUse this skill to review completed implementation work that is linked to a DEX task.\n\n## Goal\n\nValidate the implementation against the DEX task context and result, then approve or request changes.\n\n## Inputs\n\nYou should have one or more of:\n- a Craft session ID to review\n- a `dex-task::<id>` label\n- a completed DEX task ID\n\n## Review process\n\n1. Inspect the implementation session metadata and labels\n2. Find the linked `dex-task::<id>` value\n3. Read the DEX task context and recorded result\n4. Review the relevant code/files/tests without expanding scope\n5. Verify:\n   - the requested problem was actually solved\n   - the implementation matches the plan/task scope\n   - verification evidence is real and sufficient\n   - no unnecessary complexity was introduced\n6. Decide one of:\n   - **Approve**\n   - **Request changes**\n   - **Create follow-up task** when new work is genuinely separate\n\n## Session updates\n\nWhen reviewing a Craft session:\n- if approved, set the original implementation session status to `done`\n- if changes are required, set it back to `todo` and explain why\n- preserve existing labels; add `approved` or `changes-requested` only after merging with current labels\n\n## Guardrails\n\n- No scope creep during review\n- No approval without verification evidence\n- Follow-up tasks should be small, concrete, and separately testable\n\n## Output\n\nProvide a concise review summary with:\n- verdict\n- evidence checked\n- any gaps found\n- exact next action\n'''
    }
}

for slug, meta in skills.items():
    skill_dir = root / 'skills' / slug
    skill_dir.mkdir(parents=True, exist_ok=True)
    frontmatter = {
        'name': meta['name'],
        'description': meta['description']
    }
    if 'requiredSources' in meta:
        frontmatter['requiredSources'] = meta['requiredSources']
    yaml_lines = ['---']
    for key, value in frontmatter.items():
        if isinstance(value, list):
            yaml_lines.append(f'{key}:')
            for item in value:
                yaml_lines.append(f'  - {item}')
        else:
            yaml_lines.append(f'{key}: "{value}"')
    yaml_lines.append('---\n')
    (skill_dir / 'SKILL.md').write_text('\n'.join(yaml_lines) + meta['body'])
    # simple SVG icon
    initials = ''.join(part[0] for part in slug.split('-')[:2]).upper()
    (skill_dir / 'icon.svg').write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64" fill="none">
  <rect x="4" y="4" width="56" height="56" rx="14" fill="#111827"/>
  <rect x="8" y="8" width="48" height="48" rx="12" fill="#1F2937" stroke="#374151"/>
  <text x="32" y="38" text-anchor="middle" font-family="Arial, sans-serif" font-size="20" font-weight="700" fill="#E5E7EB">{initials}</text>
</svg>''')

# Automations config
automations = {
    'version': 2,
    'automations': {
        'SessionStatusChange': [
            {
                'name': 'DEX review on needs-review',
                'matcher': '^needs-review$',
                'conditions': [
                    {
                        'condition': 'state',
                        'field': 'labels',
                        'contains': 'dex'
                    }
                ],
                'permissionMode': 'ask',
                'labels': ['automation', 'review'],
                'actions': [
                    {
                        'type': 'prompt',
                        'prompt': 'Run @dex-review for implementation session ${CRAFT_SESSION_ID} ("${CRAFT_SESSION_NAME}"). The session moved from ${CRAFT_OLD_STATE} to ${CRAFT_NEW_STATE}. Review only within the completed DEX task scope, verify evidence before approving, and update the original session status to done or todo based on the verdict.'
                    }
                ]
            }
        ]
    }
}
(root / 'automations.json').write_text(json.dumps(automations, indent=2) + '\n')

# Ensure DEX storage dir exists
(root / '.dex').mkdir(exist_ok=True)
(root / '.dex' / '.gitkeep').write_text('')
