python3 - <<'PY'
import json
from pathlib import Path
p = Path('/Users/mattias/Documents/GitHub/Systembolaget-plus/automations.json')
obj = json.loads(p.read_text())
obj['automations']['LabelAdd'] = [
  {
    'name': 'Research helper on research label',
    'matcher': '^research$',
    'permissionMode': 'allow-all',
    'labels': ['automation'],
    'actions': [
      {
        'type': 'prompt',
        'prompt': 'Research helper for session ${CRAFT_SESSION_ID} ("${CRAFT_SESSION_NAME}"). Use @context7 and @brave-search to gather current best practices, official docs, relevant APIs, browser APIs, CSS techniques, existing implementation patterns, and the simplest correct modern approach. Stay in research mode only. Return concise findings the orchestrator can use to create or refine the plan.'
      }
    ]
  },
  {
    'name': 'Preflight helper on work-type label',
    'matcher': '^(feature|bug|refactor)$',
    'permissionMode': 'allow-all',
    'labels': ['automation'],
    'actions': [
      {
        'type': 'prompt',
        'prompt': 'Preflight helper for session ${CRAFT_SESSION_ID} ("${CRAFT_SESSION_NAME}") after work-type label $CRAFT_LABEL was added. Run a research-first preflight: inspect existing repo patterns, use @context7 and @brave-search for current syntax and best practices, identify the smallest workable approach, and tell the orchestrator whether it should next use @investigate-first, create a plan, or validate an existing plan. Do not implement code.'
      }
    ]
  }
]
p.write_text(json.dumps(obj, indent=2) + '\n')
PY

echo 'Automations updated.'

